"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Playful console Label: deep ink in semibold, so it names a field clearly
 * without competing with the field itself. When its control is disabled the
 * label drops to the disabled ink instead of fading to half opacity.
 *
 * Base UI has no label primitive, so this is a native label. Base UI
 * controls mark a disabled state with data-disabled rather than the
 * disabled attribute, so the label watches both.
 */
const Label = React.forwardRef<
  HTMLLabelElement,
  React.ComponentPropsWithoutRef<"label">
>(({ className, ...props }, ref) => (
  <label
    ref={ref}
    data-slot="label"
    className={cn(
      "flex select-none items-center gap-2 text-sm font-semibold leading-snug text-foreground",
      "peer-disabled:cursor-not-allowed peer-disabled:text-(--foreground-disabled)",
      "peer-data-[disabled]:cursor-not-allowed peer-data-[disabled]:text-(--foreground-disabled)",
      className,
    )}
    {...props}
  />
));
Label.displayName = "Label";

export { Label };
